import { buildStubClient } from "./__test-helpers";

// Mutable holder so each test swaps in a differently-configured stub client.
const h = vi.hoisted(() => {
  const state: { client: unknown } = { client: null };
  return { state };
});

vi.mock("@/lib/supabase/server", () => ({
  createClient: vi.fn(async () => h.state.client),
  createAdminClient: vi.fn(() => ({ __admin: true }))
}));

import {
  requireCompanyMember,
  requireCompanyAdmin,
  COMPANY_ADMIN_RANK
} from "@/lib/actions/company-auth";

const COMPANY_ID = "c0000000-0000-0000-0000-000000000001";
const USER = { id: "user_1", email: "member@example.com" };

function clientWith(opts: {
  member?: { role: string; status: string } | null;
  memberError?: { message: string } | null;
  rank?: number | null;
}) {
  return buildStubClient({
    user: USER,
    tables: {
      company_members: {
        selectSingle: {
          data: opts.member ?? null,
          error: opts.memberError ?? (opts.member ? null : { message: "0 rows" })
        }
      },
      company_roles: {
        selectSingle: {
          data: opts.rank === null || opts.rank === undefined ? null : { rank: opts.rank }
        }
      }
    }
  }).supabase;
}

beforeEach(() => {
  vi.clearAllMocks();
});

describe("requireCompanyMember", () => {
  it("returns membership with rank for an active member", async () => {
    h.state.client = clientWith({
      member: { role: "employee", status: "active" },
      rank: 30
    });

    const { user, membership } = await requireCompanyMember(COMPANY_ID);

    expect(user.id).toBe("user_1");
    expect(membership).toEqual({
      companyId: COMPANY_ID,
      role: "employee",
      rank: 30
    });
  });

  it("throws forbidden for a non-member", async () => {
    h.state.client = clientWith({ member: null });

    await expect(requireCompanyMember(COMPANY_ID)).rejects.toMatchObject({
      name: "AuthError",
      code: "forbidden"
    });
  });

  it("throws forbidden when rank is below minRank", async () => {
    h.state.client = clientWith({
      member: { role: "viewer", status: "active" },
      rank: 10
    });

    await expect(requireCompanyMember(COMPANY_ID, 60)).rejects.toMatchObject({
      code: "forbidden"
    });
  });

  it("treats an unknown role key as rank 0", async () => {
    h.state.client = clientWith({
      member: { role: "ghost_role", status: "active" },
      rank: null
    });

    await expect(requireCompanyMember(COMPANY_ID, 1)).rejects.toMatchObject({
      code: "forbidden"
    });
  });

  it("throws not_authenticated when there is no user", async () => {
    h.state.client = buildStubClient({ user: null }).supabase;

    await expect(requireCompanyMember(COMPANY_ID)).rejects.toMatchObject({
      code: "not_authenticated"
    });
  });
});

describe("requireCompanyAdmin", () => {
  it("passes for a company_admin (rank 100)", async () => {
    h.state.client = clientWith({
      member: { role: "company_admin", status: "active" },
      rank: COMPANY_ADMIN_RANK
    });

    const { membership } = await requireCompanyAdmin(COMPANY_ID);
    expect(membership.role).toBe("company_admin");
    expect(membership.rank).toBe(COMPANY_ADMIN_RANK);
  });

  it("rejects a manager (rank 60)", async () => {
    h.state.client = clientWith({
      member: { role: "manager", status: "active" },
      rank: 60
    });

    await expect(requireCompanyAdmin(COMPANY_ID)).rejects.toMatchObject({
      code: "forbidden"
    });
  });
});

/**
 * Company-scoped auth guards (multi-tenant layer).
 *
 * Pattern mirrors `auth.ts`: guards throw `AuthError` and return the
 * cookie-bound client so RLS stays the enforcement layer for member reads.
 * Role privilege is rank-based via the extensible `company_roles` catalog
 * (higher rank = more privilege; company_admin = 100), so new employer/role
 * types added as rows work without code changes.
 *
 * Server-only by transitive import of `@/lib/supabase/server` via `./auth`.
 */
import type { User } from "@supabase/supabase-js";
import { AuthError, requireUser, type DBClient } from "./auth";

/** Rank of the company_admin role seeded in the tenancy migration. */
export const COMPANY_ADMIN_RANK = 100;

export interface CompanyMembership {
  companyId: string;
  role: string;
  rank: number;
}

export interface CompanyGuardResult {
  user: User;
  supabase: DBClient;
  membership: CompanyMembership;
}

/**
 * Require the caller to be an ACTIVE member of `companyId` with role rank
 * >= `minRank`. Throws `AuthError("forbidden")` for non-members, inactive
 * memberships, and insufficient rank.
 */
export async function requireCompanyMember(
  companyId: string,
  minRank = 0
): Promise<CompanyGuardResult> {
  const { user, supabase } = await requireUser();

  const { data: member, error } = await supabase
    .from("company_members")
    .select("role, status")
    .eq("company_id", companyId)
    .eq("user_id", user.id)
    .eq("status", "active")
    .single();

  if (error || !member) {
    throw new AuthError("forbidden");
  }

  const { data: role } = await supabase
    .from("company_roles")
    .select("rank")
    .eq("key", member.role)
    .single();

  const rank = role?.rank ?? 0;
  if (rank < minRank) {
    throw new AuthError("forbidden");
  }

  return {
    user,
    supabase,
    membership: { companyId, role: member.role, rank }
  };
}

/** Require the caller to be the company's admin (rank >= 100). */
export async function requireCompanyAdmin(
  companyId: string
): Promise<CompanyGuardResult> {
  return requireCompanyMember(companyId, COMPANY_ADMIN_RANK);
}

/**
 * Shared mock builders for server-action tests.
 * Keeps every action test file consistent without making any of them
 * depend on the others' state.
 */
import { vi } from "vitest";

export type StubUser = { id: string; email: string };

export interface StubTable {
  insert: ReturnType<typeof vi.fn>;
  update: ReturnType<typeof vi.fn>;
  delete: ReturnType<typeof vi.fn>;
  select: ReturnType<typeof vi.fn>;
  eq: ReturnType<typeof vi.fn>;
  single: ReturnType<typeof vi.fn>;
}

/**
 * Build a thenable query builder where every method returns `this` and a
 * final `.single()` / await resolves to `{ data, error }`.
 *
 * Tests can assert against the call args of any method on the returned object.
 */
export function buildStubClient(opts: {
  user?: StubUser | null;
  // Per-table behavior: { insert?: {data,error}, update?: {error}, delete?: {error},
  // selectSingle?: {data,error}, selectMany?: {data,error} }.
  tables?: Record<
    string,
    {
      insert?: { data?: unknown; error?: { message: string } | null };
      update?: { data?: unknown; error?: { message: string } | null };
      delete?: { error?: { message: string } | null };
      selectSingle?: { data?: unknown; error?: { message: string } | null };
    }
  >;
}) {
  const tablesArg = opts.tables ?? {};
  const recorded: { table: string; method: string; args: unknown[] }[] = [];

  function makeChain(
    table: string,
    terminal:
      | { kind: "insert"; data?: unknown; error?: { message: string } | null }
      | { kind: "update"; error?: { message: string } | null }
      | { kind: "delete"; error?: { message: string } | null }
      | { kind: "select"; data?: unknown; error?: { message: string } | null }
  ) {
    // The builder is itself awaitable AND has `.select().single()` / `.eq()` etc.
    const builder: Record<string, unknown> = {
      select: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "select", args: a });
        return builder;
      }),
      eq: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "eq", args: a });
        return builder;
      }),
      in: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "in", args: a });
        return builder;
      }),
      order: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "order", args: a });
        return builder;
      }),
      limit: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "limit", args: a });
        return builder;
      }),
      single: vi.fn(() => {
        recorded.push({ table, method: "single", args: [] });
        if (terminal.kind === "insert" || terminal.kind === "select") {
          return Promise.resolve({ data: terminal.data ?? null, error: terminal.error ?? null });
        }
        return Promise.resolve({ data: null, error: terminal.error ?? null });
      }),
      then: (resolve: (v: { data: unknown; error: unknown }) => void) => {
        if (terminal.kind === "insert" || terminal.kind === "select") {
          resolve({ data: terminal.data ?? null, error: terminal.error ?? null });
        } else {
          resolve({ data: null, error: terminal.error ?? null });
        }
      }
    };
    return builder;
  }

  const from = vi.fn((table: string) => {
    const cfg = tablesArg[table] ?? {};
    return {
      insert: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "insert", args: a });
        return makeChain(table, {
          kind: "insert",
          data: cfg.insert?.data,
          error: cfg.insert?.error ?? null
        });
      }),
      update: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "update", args: a });
        return makeChain(table, { kind: "update", error: cfg.update?.error ?? null });
      }),
      delete: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "delete", args: a });
        return makeChain(table, { kind: "delete", error: cfg.delete?.error ?? null });
      }),
      select: vi.fn((...a: unknown[]) => {
        recorded.push({ table, method: "select", args: a });
        return makeChain(table, {
          kind: "select",
          data: cfg.selectSingle?.data,
          error: cfg.selectSingle?.error ?? null
        });
      })
    };
  });

  const user = opts.user === undefined ? { id: "user_default", email: "user@example.com" } : opts.user;

  const supabase = {
    from,
    auth: {
      getUser: vi.fn(async () => ({ data: { user }, error: null }))
    }
  };

  return { supabase, recorded };
}

